CREATE TEMPORARY VIEW all_new_item_${grass_region_without_quote} AS
select -- 获取最新可用的new item pool
     exp_tag
    ,item_id
    ,create_time
from(
    select
         item_id
        ,item_create_timestamp as create_time
    from srdi_mart.dim_sr_data_warehouse_item
    where grass_region in (${grass_region})
    and local_date = data_infra.max_pt('srdi_mart.dim_sr_data_warehouse_item', 'local_date', "grass_region=${grass_region} and local_date<${regional_date}")
    and datediff(${regional_date}, from_unixtime(item_create_timestamp, 'yyyy-MM-dd')) < 90 -- new item 上线后，按东八区的自然日结算，第91天的第一个小时消失
) a
lateral view explode(array('T1')) b as exp_tag
;
--sql_divide_splitter--
-- 获取离线最大可用分区
CREATE TEMPORARY VIEW offline_data_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,item_id
    ,platform_imp_cnt
    ,explore_imp_cnt
    ,explore_click_cnt
    ,explore_order_cnt
FROM srdi_mart.dws_sr_data_warehouse_ni_boost_explore_item_nd
where grass_region in (${grass_region})
and regional_date = data_infra.max_pt('srdi_mart.dws_sr_data_warehouse_ni_boost_explore_item_nd', 'regional_date', "grass_region=${grass_region} and regional_date<${regional_date}")
;
--sql_divide_splitter--
-- 获取实时从离线有到当前时刻的部分
CREATE TEMPORARY VIEW realtime_raw_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,item_id
    ,explore_imp_cnt
    ,explore_click_cnt
    ,explore_order_cnt
FROM paimon.srdi_mart.dws_sr_data_warehouse_ni_boost_item_realtime_1d
where grass_region in (${grass_region})
and regional_date <= ${regional_date} -- 一天内不支持backfill，下游用最大可用分区即可;左边界用离线有的那天的后一天，以此来完整衔接
-- 注意这里取最大可用分区函数里的表名字，不是1d自己
and regional_date > data_infra.max_pt('srdi_mart.dws_sr_data_warehouse_ni_boost_explore_item_nd', 'regional_date', "grass_region=${grass_region} and regional_date<${regional_date}")
;
--sql_divide_splitter--
-- 获取实时从离线有到当前时刻的部分
CREATE TEMPORARY VIEW realtime_data_${grass_region_without_quote} AS
select
     a.exp_tag
    ,a.item_id
    ,b.platform_imp_cnt
    ,explore_imp_cnt
    ,explore_click_cnt
    ,explore_order_cnt
from (
    SELECT
         exp_tag
        ,item_id
        ,explore_imp_cnt
        ,explore_click_cnt
        ,explore_order_cnt
    FROM realtime_raw_${grass_region_without_quote}
    where exp_tag like 'T%' -- 只要指定策略的
) a
left join (
    SELECT
         item_id
        ,sum(explore_imp_cnt) as platform_imp_cnt
    FROM realtime_raw_${grass_region_without_quote}
    group by item_id --拼凑出全平台累计的，也就是不关注实验桶的
) b on a.item_id =b.item_id
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW merged_data_${grass_region_without_quote} AS
select
     exp_tag
    ,item_id
    ,sum(platform_imp_cnt)  as platform_imp_cnt
    ,sum(explore_imp_cnt)   as explore_imp_cnt
    ,sum(explore_click_cnt) as explore_click_cnt
    ,sum(explore_order_cnt) as explore_order_cnt
from (
   select
   *
   from offline_data_${grass_region_without_quote}
   union all
   select
   *
   from realtime_data_${grass_region_without_quote}
) a
group by exp_tag,item_id
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_ni_boost_item_hourly_nd
PARTITION (grass_region = ${grass_region}, regional_date = ${regional_date}, regional_hour = ${regional_hour})
select
     a.exp_tag
    ,a.item_id
    ,a.create_time
    ,platform_imp_cnt
    ,explore_imp_cnt
    ,explore_click_cnt
    ,explore_order_cnt
from all_new_item_${grass_region_without_quote} a
left join merged_data_${grass_region_without_quote} b on a.item_id=b.item_id and a.exp_tag=b.exp_tag
;
